     1→// broken_discount.rs - 의도적 로직 버그 (Self-Healing 테스트용)
     2→// 버그: 할인율 계산에서 100 대신 10으로 나눔 → 10배 과다 할인
     3→
     4→fn calculate_discount(price: f64, discount_percent: f64) -> f64 {
     5→    // 버그: /10.0 이어야 하는 게 아니라 /100.0 이어야 함
     6→    // 30% 할인 → price * 0.3 이어야 하는데 price * 3.0 이 됨
     7→    price - (price * discount_percent / 10.0)
     8→}
     9→
    10→fn apply_coupon(price: f64, coupon_code: &str) -> f64 {
    11→    match coupon_code {
    12→        "SAVE10" => calculate_discount(price, 10.0),
    13→        "SAVE20" => calculate_discount(price, 20.0),
    14→        "SAVE30" => calculate_discount(price, 30.0),
    15→        _ => price,
    16→    }
    17→}
    18→
    19→#[cfg(test)]
    20→mod tests {
    21→    use super::*;
    22→
    23→    #[test]
    24→    fn test_10_percent_discount() {
    25→        // 100원의 10% 할인 → 90원이어야 함
    26→        let result = apply_coupon(100.0, "SAVE10");
    27→        assert_eq!(result, 90.0);
    28→    }
    29→
    30→    #[test]
    31→    fn test_30_percent_discount() {
    32→        // 100원의 30% 할인 → 70원이어야 함
    33→        let result = apply_coupon(100.0, "SAVE30");
    34→        assert_eq!(result, 70.0);
    35→    }
    36→
    37→    #[test]
    38→    fn test_no_coupon() {
    39→        let result = apply_coupon(100.0, "INVALID");
    40→        assert_eq!(result, 100.0);
    41→    }
    42→}
